windows.close:
{(e) => {
        const press = backdropPress.current;
        backdropPress.current = null;
        if (!press || !isBackdrop(e.target)) return;
        if (Math.hypot(e.clientX - press.x, e.clientY - press.y) > TAP_SLOP_PX) return;
        close();
      }}

windows.size:
{`fixed inset-x-0 z-[60] flex flex-col bg-surface-1 border-divider ${
            keyboard
              ? 'border-b rounded-b-xl pb-2'
              : 'bottom-0 h-[calc(100dvh-env(safe-area-inset-top)-1rem)] border-t rounded-t-xl pb-[max(0.75rem,env(safe-area-inset-bottom))]'
          }`}
